function normalizeStoryNode(node: StoryNode): StoryNode {
  const normalized = node.choices?.length
    ? {
        ...node,
        choices: node.choices.map((choice, index) => ({
          ...choice,
          id: choice.id ?? `${node.id}__${index}`,
        })),
      }
    : node;

  if (normalized.speaker !== 'nova') return normalized;
  if (normalized.type !== 'text' && normalized.type !== 'image') return normalized;
  return {
    ...normalized,
    content: cleanChatText(normalized.content),
  };
}

export const storyNodes: StoryNode[] = rawStoryNodes.map(normalizeStoryNode);

// Create a map for fast lookup
export const storyNodeMap: Map<string, StoryNode> = new Map(
  storyNodes.map(n => [n.id, n])
);
